import{_ as i,a0 as s,w as u,s as l,ao as a,I as o,x as t,a1 as p,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const q=JSON.parse('{"title":"戴文的Linux内核专题：21 配置内核 (17) | LCTT x X-CMD","titleTemplate":false,"description":"戴文的Linux内核专题：21 配置内核 (17) | LCTT (The Linux Kernel) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"戴文的Linux内核专题：21 配置内核 (17) | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"戴文的Linux内核专题：21 配置内核 (17) | LCTT (The Linux Kernel) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The Linux Kernel/21 The Linux Kernel--Configuring the Kernel Part 17","title":"戴文的Linux内核专题：21 配置内核 (17)","tag":"The Linux Kernel","desc":""},"relativePath":"The Linux Kernel/21 The Linux Kernel--Configuring the Kernel Part 17.md","filePath":"[post].md"}'),d={name:"The Linux Kernel/21 The Linux Kernel--Configuring the Kernel Part 17.md"};function C(g,e,T,I,f,m){const n=s("Link");return u(),l("div",null,[e[13]||(e[13]=a('<h1 id="戴文的linux内核专题-21-配置内核-17" tabindex="-1">戴文的Linux内核专题：21 配置内核 (17) <a class="header-anchor" href="#戴文的linux内核专题-21-配置内核-17" aria-label="Permalink to “戴文的Linux内核专题：21 配置内核 (17)”">​</a></h1><p><img src="http://www.linux.org/attachments/slide-jpg.605/" alt=""></p><p>你好！这篇文章会覆盖不同的驱动。</p><p>首先&quot;virtio console&quot;是一种用于hypervisors的虚拟控制台驱动。</p><p>&quot;IPMI top-level message handler&quot;是用于IPMI系统的消息管理器。IPMI代表的是&quot;Intelligent Platform Management Interface&quot;(智能平台管理系统)。IPMI是一种不需要shell通过网络管理系统的接口。</p><p>&quot;/dev/nvram support&quot;允许系统读取和写入实时时钟的内存。通常上，这个特性用于在掉电时保存数据。</p><p>下面一个驱动支持Siemens R3964包驱动(Siemens R3964 line discipline)。这个是设备对设备协议</p><p>现在，我们可以进入PCMCIA字符设备驱动。然而，大多数这里的驱动是供货商/设备特定的。</p><p>原始块设备驱动允许块设备绑定到设备文件上/dev/raw/rawN(RAW driver (/dev/raw/rawN))。这么做的好处是高效的零拷贝。然而，大多数软件更偏好通过/dev/sd** 或者 /dev/hd**访问存储设备。</p><p>下面，可以设置支持的原始设备的最大数量。</p><p>下面的驱动可以生成设备文件/dev/hpet (HPET - High Precision Event Timer)。</p><p>注意：你们中很多人可能会想知道为什么要启用这些设备文件问题。好的，这些设备文件充当了一个软件和硬件之间的接口。</p><p>通过这个驱动可以映射HPET驱动(Allow mmap of HPET)。映射是一个生成设备和文件在内存中的地址列表。文件接着可以通过内存地址更快地找到并且接着指挥硬盘从地址中得到数据。</p><p>&quot;Hangcheck timer&quot;用于检测系统是否被锁定。这个定时器监视着锁定进程。当一个进程被冻结了，定时器就开启。当定时器停止后，如果进程还没有重启或者关闭，那么定时器会强迫进程关闭。</p><blockquote><p>引用Linus Torvalds的话：可移植性是对于那些无法写新程序的人而言的。</p></blockquote><p>使用Trusted Computing Group(可信赖计算组)规范的TPM安全芯片会需要这个驱动(TPM Hardware Support)。</p><p>现在，我们可以进入I2C设备。I2C代表的是&quot;Inter-Integrated Circuit&quot;(内部集成电路)并经常被成为&quot;eye two see&quot;。然而，一些人会说&quot;eye squared see&quot;。I2C是一种串行总线标准。</p><p>一些旧的软件将I2C适配器作为类设备，但是如今的软件不会这么做(Enable compatibility bits for old user-space)。所以，这个驱动会提供对旧软件的向后支持。</p><p>接下来，可以生成I2C设备文件(I2C device interface)。</p><p>I2C可以通过这个驱动提供复用支持(I2C bus multiplexing support)。</p><p>I2C可以通过这个驱动支持GPIO控制的复用(GPIO-based I2C multiplexer)。</p><p>对于开发者用这个驱动可以在I2C和SMBus上执行不同的测试(I2C/SMBus Test Stub)。</p><p>I2C系统启用这个特性可以生成调试信息(I2C Core debugging messages)。</p><p>下一个驱动生成额外的I2C调试信息(I2C Algorithm debugging messages)。</p><blockquote><p>引用Linus Torvalds的话：Linux中没有原始设备的原因似乎我个人任何原始设备是一个愚蠢的注意。</p></blockquote><p>下面的驱动会使I2C驱动生成调试信息(I2C Bus debugging messages)。</p><p>接下来，我们有串行外设接口(Serial Peripheral Interface)支持(SPI support)。SPi是一种用于SPI总线的同步串行协议。</p><p>在这之后，有一个驱动用于高速同步串行接口(High speed synchronous Serial Interface support)支持(HSI support)。HSI是一种同步串行协议。</p><p>PPS同样在Linux内核中支持(PPS support)。</p><p>&quot;IP-over-InfiniBand&quot;驱动支持IP包通过InfiniBand(译注：一种无限带宽技术)传输。</p><p>在这之后，有一个调试驱动用于IP-over-InfiniBand(IP-over-InfiniBand debugging)。</p><p>SCSI的RDMA协议同样可以通过InfiniBand传输(InfiniBand SCSI RDMA Protocol)。</p><p>这里同样有一种通过InfiniBand传输iSCSI协议的扩展(iSCSI Extensions for RDMA (iSER))。</p><p>有时候，错误发生在了整个系统必须知道的核心系统中(EDAC (Error Detection And Correction) reporting)。这个驱动发送核心给系统。通常地，这类底层错误由处理器中报告并接着由这个驱动让其他系统进程知道或者处理错误。</p><p>这个驱动提供了在老版本中的sysfs中使用的过时EDAC的支持(EDAC legacy sysfs)。</p><p>EDAC可以用来设置发送调试信息给Linux的日志系统(Debugging)。</p><blockquote><p>引用Linus Torvalds的话：没有人可以第一次创造如此好的代码，除了我。</p></blockquote><p>&quot;Machine Check Exceptions&quot;(机器检测异常)(MCEs)通过这个驱动被转化成可读的信息(Decode MCEs in human-readable form (only on AMD for now))。MCEs是由CPU检测到的硬件错误。MCEs通常触发内核错误。</p><p>将MCE解码成可读的形式的过程可以被注射用于测试错误处理(Simple MCE injection interface over /sysfs)。</p><p>下一个驱动允许错误在内存中被检测到并纠正(Main Memory EDAC (Error Detection And Correction) reporting)。</p><p>下面，还有很多用于特定设备组的检测和纠正错误的驱动。</p><blockquote><p>引用Linus Torvalds的话：理论和实践有时会冲突。那这个发生时，理论输了。每次都是。</p></blockquote><p>现在我们可以进入实时时钟(&quot;Real Time Clock&quot;)。这通常缩写为&quot;RTC&quot;。RTC一直跟随着时间。</p><p><img src="http://www.linux.org/attachments/rtc-png.606/" alt=""></p><p>下面的设定允许用户在Linux系统中使用RTC时间作为&quot;挂钟&quot;时间(Set system time from RTC on startup and resume)。这个挂钟是我们在桌面上或者通过&quot;date&quot;命令看到的时间。</p><p>另外，挂钟可以通过NTP服务器得到时间并与RTC同步(Set the RTC time based on NTP synchronization)。</p><p>一些系统有几个RTC，所以用户必须设置哪一个是默认 (RTC used to set the system time)。最好设置第一个(/dev/rtc0)为主时钟。</p><p>可以设置RTC系统的调试特性(RTC debug support)。</p><p>RTC可以使用不同的接口给予操作系统当前时间。使用sysfs会需要这个驱动(/sys/class/rtc/rtcN (sysfs))，而似乎用proc需要这个驱动 (/proc/driver/rtc (procfs for rtcN))。特殊的RTC字符设备可以生成并使用 (/dev/rtcN (character devices))。shell命令&quot;hwclock&quot;使用/dev/rtc,所以RTC字符设备。</p><p>下一个驱动允许在/dev接口上模拟RTC中断(RTC UIE emulation on dev interface)。这个驱动读取时钟时间并允许新的时间从/dev中检索。</p><p>RTC系统可以通过测试驱动测试(Test driver/device)。</p><p>下面，我们会讨论直接内存访问系统。DMA是硬件独立于处理器的内存访问过程。DMA增加的系统性能因为处理器将做得更少如果硬件自身做了更多的任务。不然，硬件会等待处理器完成任务。</p><p>这是调试DMA系统的调试引擎(DMA Engine debugging)。</p><p>接下来，有许多的供货商/设备特定驱动用于DMA支持。</p><p>一些DMA通过这个驱动支持大端读取和写入(Use big endian I/O register access)。</p><p>大端指的是二进制码的排列。英语国家的数字系统将数字的最大端放在左边。比如，数字17，最左的数字是放置十位的地方大于个位。在大端中，每字节最大的放在左边。字节有8位。比如：10110100。每一处都有相应的值128、64、32、16、8、4、2、1。所以提到的为被转换成十进制180。</p><p>DMA系统可以使用网络减小CPU使用(Network: TCP receive copy offload)。</p><p>&quot;DMA Test Client&quot;用于测试DMA系统。</p><p>下一篇文章中，我们会讨论显示/视频驱动。谢谢！</p>',59)),o("p",null,[e[1]||(e[1]=t("参考：Linus Torvalds的引用来自于:",-1)),p(n,{href:"http://en.wikiquote.org/wiki/Linus_Torvalds"},{default:r(()=>[...e[0]||(e[0]=[t("http://en.wikiquote.org/wiki/Linus_Torvalds",-1)])]),_:1})]),e[14]||(e[14]=o("hr",null,null,-1)),o("p",null,[e[3]||(e[3]=t("via: ",-1)),p(n,{href:"http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-17.4875/"},{default:r(()=>[...e[2]||(e[2]=[t("http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-17.4875/",-1)])]),_:1})]),o("p",null,[e[6]||(e[6]=t("译者：",-1)),p(n,{href:"https://github.com/geekpi"},{default:r(()=>[...e[4]||(e[4]=[t("geekpi",-1)])]),_:1}),e[7]||(e[7]=t(" 校对：",-1)),p(n,{href:"https://github.com/wxy"},{default:r(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[10]||(e[10]=t("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原创翻译，",-1)),p(n,{href:"http://linux.cn/"},{default:r(()=>[...e[9]||(e[9]=[t("Linux中国",-1)])]),_:1}),e[12]||(e[12]=t(" 荣誉推出",-1))])])}const P=i(d,[["render",C]]);export{q as __pageData,P as default};
